create role tienda_api nologin nobypassrls;
create table settings (id integer primary key default 1 check(id=1), owner_email text not null, opening_date date, opening_done boolean not null default false);
create table categories (id uuid primary key, name text not null unique, parent_id uuid references categories(id));
create table suppliers (id uuid primary key, name text not null, email text, reference text, active boolean not null default true, created_at timestamptz not null default now());
create table products (id uuid primary key, sku text not null unique, name text not null, brand text not null default '', category_id uuid references categories(id), variant text not null default '', clip_id text unique, price_cents bigint not null default 0 check(price_cents>=0), active boolean not null default true, created_at timestamptz not null default now());
create table purchases (id uuid primary key, date date not null, supplier_id uuid references suppliers(id), reference text not null, freight_cents bigint not null check(freight_cents>=0), tax_cents bigint not null check(tax_cents>=0), total_cents bigint not null check(total_cents>=0), notes text not null default '', created_at timestamptz not null default now(), unique(supplier_id,reference));
create table purchase_lines (id uuid primary key, purchase_id uuid not null references purchases(id), product_id uuid not null references products(id), quantity numeric(20,6) not null check(quantity>0), unit_cost numeric(20,6) not null check(unit_cost>=0), cost_cents bigint not null check(cost_cents>=0));
create table expense_templates (id uuid primary key, category text not null, concept text not null, amount_cents bigint not null check(amount_cents>=0), tax_cents bigint not null check(tax_cents>=0), active boolean not null default true);
create table expenses (id uuid primary key, date date not null, category text not null, concept text not null, amount_cents bigint not null check(amount_cents>=0), tax_cents bigint not null check(tax_cents>=0), kind text not null default 'operating' check(kind in ('operating','asset')), notes text not null default '', template_id uuid references expense_templates(id), created_at timestamptz not null default now(), unique(template_id,date));
create table sync_runs (id uuid primary key, from_date date not null, to_date date not null, status text not null check(status in ('running','preview','confirmed','failed')), row_count integer not null default 0, error text, created_at timestamptz not null default now());
create table imports (id uuid primary key, filename text not null, file_hash text not null, payload_hash text not null unique, rows jsonb not null, errors jsonb not null, source text not null check(source in ('clip_api','clip_import')), sync_id uuid references sync_runs(id), status text not null default 'preview' check(status in ('preview','confirmed')), created_at timestamptz not null default now());
create table incomes (id uuid primary key, from_date date not null, to_date date not null check(to_date>from_date), channel text not null, source text not null check(source in ('clip_api','clip_import','manual_summary')), external_id text unique, import_id uuid references imports(id), description text not null, category_id uuid references categories(id), product_id uuid references products(id), quantity numeric(20,6) check(quantity>0), gross_cents bigint not null check(gross_cents>=0), net_cents bigint check(net_cents>=0), cogs_cents bigint check(cogs_cents>=0), fees_cents bigint check(fees_cents>=0), refund_cents bigint not null default 0 check(refund_cents>=0 and refund_cents<=gross_cents), method text not null default 'Sin identificar', status text not null default 'active' check(status in ('active','cancelled','replaced')), notes text not null default '', created_at timestamptz not null default now());
create index incomes_period on incomes(from_date,to_date) where status='active';
create table inventory_movements (id uuid primary key, product_id uuid not null references products(id), date date not null, quantity numeric(20,6) not null, value_cents bigint not null, kind text not null check(kind in ('opening','purchase','sale','adjustment','reversal')), purchase_line_id uuid unique references purchase_lines(id), income_id uuid unique references incomes(id), reason text not null, created_at timestamptz not null default now());
create index inventory_by_product on inventory_movements(product_id,date);
create table cash_accounts (id text primary key, name text not null, kind text not null check(kind in ('available','pending')));
insert into cash_accounts values ('cash','Efectivo','available'),('bank','Banco','available'),('clip','Clip por liquidar','pending');
create table cash_movements (id uuid primary key, date date not null, account_id text not null references cash_accounts(id), amount_cents bigint not null check(amount_cents<>0), kind text not null check(kind in ('opening','collection','purchase','expense','refund','transfer','contribution','withdrawal')), purchase_id uuid references purchases(id), expense_id uuid references expenses(id), income_id uuid references incomes(id), transfer_id uuid, notes text not null, created_at timestamptz not null default now(), check(num_nonnulls(purchase_id,expense_id,income_id)<=1));
create unique index income_cash_once on cash_movements(income_id) where income_id is not null and kind='collection';
create table monthly_closes (id uuid primary key, month text not null unique check(month ~ '^\d{4}-(0[1-9]|1[0-2])$'), status text not null check(status in ('closed','reopened')), version integer not null default 1, snapshot jsonb not null, checklist jsonb not null, created_at timestamptz not null default now());
create table audit_events (id uuid primary key, entity text not null, entity_id text not null, action text not null, actor text not null, reason text not null, data jsonb not null, created_at timestamptz not null default now());
create table idempotency_requests (key text primary key, payload_hash text not null, result jsonb not null, created_at timestamptz not null default now());
create table fee_rules (id uuid primary key, method text not null, percent numeric(8,4) not null check(percent between 0 and 100), fixed_cents bigint not null check(fixed_cents>=0), tax_percent numeric(8,4) not null check(tax_percent between 0 and 100), msi_percent numeric(8,4) not null check(msi_percent between 0 and 100), unique(method));
-- La API verifica la identidad y establece el autor dentro de cada transacción.
-- El rol no se concede a los roles de la Data API de Supabase.
do $$ declare t text; begin
 for t in select tablename from pg_tables where schemaname='public' and tablename <> 'schema_migrations' loop
  execute format('alter table public.%I enable row level security',t);
  execute format('alter table public.%I force row level security',t);
  execute format('create policy private_owner on public.%I to tienda_api using (current_setting(''app.author'',true) = current_setting(''app.owner'',true) and current_setting(''app.owner'',true) <> '''') with check (current_setting(''app.author'',true) = current_setting(''app.owner'',true) and current_setting(''app.owner'',true) <> '''')',t);
  execute format('grant select, insert, update on public.%I to tienda_api',t);
  if exists(select 1 from pg_roles where rolname='anon') then execute format('revoke all on public.%I from anon, authenticated',t); end if;
 end loop;
end $$;
revoke update on audit_events from tienda_api;
